const S = { boot: null, attempt: null, index: 0, answers: {}, dirty: false, saveTimer: null, timer: null, submitting: false, admin: false, adminTab: 'dashboard', data: null, renderId: 0 };
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const idPath = v => encodeURIComponent(v);
const date = v => v ? new Date(v).toLocaleString('zh-CN', {hour12: false}) : '待主办方确认';
const shortDate = v => v ? new Date(v).toLocaleDateString('zh-CN', {month:'2-digit',day:'2-digit'}) : '待定';
const money = v => (Number(v || 0) / 100).toFixed(2);
const isDemo = () => S.boot?.mode !== 'production';
function inWeChat() { return /MicroMessenger/i.test(navigator.userAgent); }
const cfg = () => S.boot?.config || {};
function copy(k,fallback){ const v=cfg().copy?.[k]; return (typeof v==='string' && v.trim())?v:fallback; }
function mixHex(hex, target, weight){
  const h=String(hex||'').replace('#',''); const t=String(target||'').replace('#','');
  if(!/^[0-9a-f]{6}$/i.test(h) || !/^[0-9a-f]{6}$/i.test(t)) return hex;
  const a=[0,2,4].map(i=>parseInt(h.slice(i,i+2),16));
  const b=[0,2,4].map(i=>parseInt(t.slice(i,i+2),16));
  const c=a.map((v,i)=>Math.round(v+(b[i]-v)*weight));
  return '#'+c.map(v=>v.toString(16).padStart(2,'0')).join('');
}
function applyTheme(hex){
  if(!/^#[0-9a-f]{6}$/i.test(hex||'')) return;
  const root=document.documentElement;
  root.style.setProperty('--red',hex);
  root.style.setProperty('--red-dark',mixHex(hex,'#0b2342',.55));
  root.style.setProperty('--red-ink',mixHex(hex,'#0b2342',.72));
  root.style.setProperty('--red-light',mixHex(hex,'#ffffff',.92));
  const meta=document.querySelector('meta[name=theme-color]'); if(meta)meta.content=hex;
}
function applyTemplate(t){ document.body.dataset.template=['1','2','3'].includes(String(t))?String(t):'1'; }
function applyHero(url){
  const safe=/^(https:\/\/|\/static\/)/.test(url||'')?url:'/static/hero-bg.svg';
  document.documentElement.style.setProperty('--hero-image',`url("${safe}")`);
}

