function toast(message) { const el = $('#toast'); el.textContent = message; el.classList.add('show'); clearTimeout(toast.t); toast.t = setTimeout(() => el.classList.remove('show'), 3600); }
async function api(path, method = 'GET', body) { const options = {method, credentials:'same-origin', headers:{}}; if(body !== undefined) { if(body instanceof FormData) options.body = body; else { options.headers['Content-Type'] = 'application/json'; options.body = JSON.stringify(body); }} const response = await fetch(path, options); let data; try { data = await response.json(); } catch { throw new Error(`服务暂时不可用（${response.status}）`); } if(!response.ok) { const error = new Error(data.error || `请求失败（${response.status}）`); error.status = response.status; throw error; } return data; }
function modal(title, content) { $('#modal-root').innerHTML = `<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><button class="modal-close" data-action="close-modal" aria-label="关闭">×</button><h2>${esc(title)}</h2>${content}</section></div>`; setTimeout(() => $('#modal-root input, #modal-root button.btn')?.focus(), 30); }
function closeModal() { $('#modal-root').innerHTML = ''; }
function empty(text) { return `<div class="empty"><div class="empty-symbol">${icon('info')}</div>${esc(text)}</div>`; }
function nav(route) { location.hash = route; }
function demoRibbon() { return (isDemo() ? '<div class="demo-ribbon">演示环境 · 题目与奖品仅供体验 · 不发放真实红包，不代表正式活动规则</div>' : '') + (S.boot?.user?.is_test ? '<div class="test-ribbon">测试账号 · 不限答题次数 · 固定 100 分</div>' : ''); }
function shell(content, active = 'home') { app.innerHTML = `<header class="site-header"><div class="header-inner">${brand()}<nav class="desktop-nav" aria-label="主导航">${[['home','活动首页'],['rules','活动规则'],['ranking','积分榜单'],['awards','我的奖品']].map(([r,t])=>`<a href="#${r}" class="${active===r?'active':''}">${t}</a>`).join('')}</nav><button class="user-chip" data-action="${S.boot?.user?'account':'login'}" aria-label="我的账号">${S.boot?.user ? (S.boot.user.avatar?`<img class="user-avatar" src="${esc(S.boot.user.avatar)}" alt="">`:'<span class="user-avatar-fallback" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="12" cy="8" r="3.5"/><path d="M4.5 20c.8-4 3.5-6 7.5-6s6.7 2 7.5 6"/></svg></span>') : '登录参与 →'}</button></div></header>${demoRibbon()}<main class="page">${content}</main><footer class="footer">${esc(cfg().organizer || '呼伦贝尔政法')}<br>${esc(cfg().footerText || '学法知法 · 守护平安 · 共建美好家园')}<a href="#admin">管理入口</a></footer><nav class="mobile-nav" aria-label="移动导航">${[['home','home','首页'],['rules','rules','规则'],['ranking','ranking','榜单'],['awards','gift','奖品']].map(([r,i,t])=>`<a href="#${r}" class="${active===r?'active':''}"><span class="nav-symbol" aria-hidden="true">${icon(i)}</span>${t}</a>`).join('')}</nav>`; if(S.boot?.user && !String(location.hash||'').startsWith('#admin')) setupShare().catch(()=>{}); }
async function refreshBoot() { S.boot = await api('/api/bootstrap'); S.clockOffset = S.boot.serverTime ? new Date(S.boot.serverTime).getTime() - Date.now() : 0; applyTheme(cfg().themeColor); applyTemplate(cfg().template); applyHero(cfg().heroImage); return S.boot; }
function home() { const b = S.boot, c = cfg(), a = b.account || {}; const remaining = Number(a.freeRemaining || 0) + Number(a.reviveRemaining || 0); const activeAttempt = b.activeAttempt; const title = c.title || '深化扫黑除恶专项斗争有奖答题活动'; shell(`<section class="hero"><div class="hero-copy"><div class="eyebrow">${esc(c.homeEyebrow || '深化扫黑除恶 · 共建平安家园')}</div><h1>${esc(title).replace('有奖答题','<br><span>有奖答题</span>')}</h1><p>${esc(c.homeIntro || '让法治精神深入人心，让平安建设与你同行。')}</p><div class="hero-meta"><span>● ${esc(statusName(b.state))}</span><span>${shortDate(c.startAt)} — ${shortDate(c.endAt)}</span><span>${esc(c.homeMeta || '全民参与 · 共护平安')}</span></div></div></section><div class="home-grid"><section class="card"><div class="card-title">${icon('list')}${esc(c.homeCardTitle || '今天，也为平安加一分')}</div><div class="stats"><div class="stat"><strong>${S.boot.user?(S.boot.user.is_test?'不限':remaining):'—'}</strong><span>${S.boot.user?.is_test?'测试答题':'今日剩余机会'}</span></div><div class="stat"><strong>${a.points ?? 0}</strong><span>我的累计积分</span></div><div class="stat"><strong>${c.passScore ?? 80}</strong><span>抽奖达标分数</span></div></div><button class="btn full" data-action="start" ${['pending','paused','ended'].includes(b.state)?'disabled':''}>${activeAttempt?'继续上次答题':b.state==='ended'?'本期活动已结束':b.state==='paused'?'活动暂停，请稍后再来':b.state==='pending'?'活动即将开始':esc(c.homeCta || '开始答题，赢取好礼')} <span>→</span></button><p class="help center">每套 10 题 · 单选 5 题 + 多选 5 题 · 满分 100 分</p>${b.latestResult?'<div class="center"><button class="text-link" data-action="latest">查看最近一次成绩 →</button></div>':''}<div class="steps"><span class="step"><b>01</b> 学习知识</span><span class="step"><b>02</b> 答题达标</span><span class="step"><b>03</b> 抽取好礼</span><span class="step"><b>04</b> 积分评优</span></div></section><section class="card"><div class="card-title">${icon('gift')}${esc(c.homeGiftTitle || '知识有力量，参与有惊喜')}</div><div class="prize-preview"><span class="prize-icon">${icon('coin')}</span><div><h3>答题达标 · 随机好礼</h3><p>现金红包 / 积分奖励</p></div></div><div class="prize-preview"><span class="prize-icon">${icon('trophy')}</span><div><h3>积分前 ${c.winnerCount || 50} 名 · 荣誉奖励</h3><p>${esc(c.awardDescription || '实物奖励以主办方公布方案为准')}</p></div></div><div class="notice-box">${b.state==='ended'?'本期答题已结束，欢迎查看封榜公示与领奖信息。':'每一次学习，都让守护平安更有力量。奖品数量有限，具体规则请查看活动说明。'}</div><a class="text-link" href="#${b.state==='ended'?'winners':'rules'}">${b.state==='ended'?'查看获奖公示':'了解活动规则'} →</a></section></div><div class="section-heading"><h2>学法明理，共筑平安</h2><small>法治同行 · 全民参与</small></div><div class="feature-row"><a href="#rules" class="card feature"><span class="feature-symbol">${icon('rules')}</span><span><strong>答题前，先了解规则</strong><small>题型分值与参与方式一目了然</small></span></a><a href="#ranking" class="card feature"><span class="feature-symbol">${icon('ranking')}</span><span><strong>每一分努力，都被看见</strong><small>查看积分排名，与大家共同进步</small></span></a><a href="#${b.state==='ended'?'winners':'awards'}" class="card feature"><span class="feature-symbol">${icon('gift')}</span><span><strong>${b.state==='ended'?'获奖名单公示':'我的奖品与领奖信息'}</strong><small>查看奖励记录，及时登记收货信息</small></span></a></div>`); }
function rules() { const c=cfg(); shell(`<div class="narrow"><a class="back" href="#home">← 返回首页</a><div class="page-heading"><div><div class="eyebrow">活动说明</div><h1>活动规则</h1><p>${esc(c.rulesIntro || '开始前花一分钟，了解这场知识之旅。')}</p></div></div><section class="card rules-list"><div class="rule-item"><h3>活动时间与主办单位</h3><p>${date(c.startAt)} 至 ${date(c.endAt)}<br>主办单位：${esc(c.organizer || '待确认')}</p></div><div class="rules-default" style="${c.rulesText?'display:none':''}"><div class="rule-item"><h3>答题与达标</h3><p>每套 10 题，单选 5 题，每题 8 分；多选 5 题，每题 12 分。多选须全部选对，漏选、多选、错选均不得分。满分 100 分，达到 ${c.passScore ?? 80} 分可获得本套抽奖资格。${Number(c.timeLimitSeconds)>0?`每题限时 ${Math.round(c.timeLimitSeconds/10)} 秒，超时自动进入下一题，未作答不得分；整卷最多 ${Math.round(c.timeLimitSeconds/60)} 分钟。`:'以页面计时提示为准。'}<br>例如：4 道单选 + 4 道多选答对，得 80 分；5 道单选 + 3 道多选答对，仅得 76 分。答对 8 题不一定达标。</p></div><div class="rule-item"><h3>参与机会与断点续答</h3><p>每日免费机会 ${c.dailyFree ?? 1} 次，按服务器自然日重置。当日复活上限 ${c.reviveLimit ?? 1} 次，机会不跨天累计。未达标后，按页面实际开放的复活方式申请；复活成功后重新开始一套新题并重新计时（每题 2 分钟、整卷最多 20 分钟），不继承上一套剩余时间。答题进度自动保存，退出后在本套计时结束前可继续作答；计时结束自动交卷，未作答不得分；不设额外的恢复有效期。</p></div><div class="rule-item"><h3>随机抽奖与领奖</h3><p>达标后可参加一次抽奖，奖品包含${(S.boot.prizes||[]).filter(p=>p.type!=='none').map(p=>esc(p.name)).join('、') || '微信红包及主题宣传品'}。库存、预算与个人中奖上限均由服务端核验。红包状态以实际发放记录为准；实物中奖后请填写真实收货资料，或选择线下领取。${isDemo()?'当前为演示环境，所有抽奖均不产生真实奖品或资金。':''}</p></div><div class="rule-item"><h3>积分排名与评优</h3><p>取单套最高分（低于 80 分也可上榜；最高分转为积分，加抽奖积分；多套不累计。总积分降序排名，同分依次比较总用时、首次达标时间、最后答题时间，仍相同则并列。结束后封榜，前 ${c.winnerCount || 50} 名参与评优。${esc(c.awardDescription || '具体奖品档位以主办方正式公告为准。')}</p></div><div class="rule-item"><h3>公平参与与个人信息</h3><p>同一微信账号对应唯一参与身份。成绩、次数、奖品及活动状态以服务端核验为准。姓名、电话、地址仅用于本次活动奖品发放，不会用于其他用途，也不会向无关第三方泄露，请勿在公开昵称中填写手机号等敏感信息。</p></div><div class="rule-item"><h3>微信授权与个人信息</h3><p>登录时经你授权获取微信昵称、头像，仅用于活动页面展示、参与者识别和关注状态校验，不用于其他商业用途。活动结束后按主办方要求处理，不向无关第三方提供。</p></div></div>${(c.rulesText||'').trim()?`<div class="rule-item"><h3>活动规则</h3><p>${esc(c.rulesText).replace(/\n/g,'<br>')}</p></div>`:''}<button class="btn full" data-action="accept-rules">我已了解，进入活动 →</button></section></div>`,'rules'); }
function login() { if(!isDemo() || /MicroMessenger/i.test(navigator.userAgent)) { location.href='/api/auth/wechat'; return; } modal(copy('loginTitle','登录演示账号'),`<div class="notice-box">${esc(cfg().loginTip || '此账号仅用于本地体验，不会连接微信或发放真实奖品。')}</div><form id="demo-login"><label class="field">参与昵称<input name="nickname" maxlength="24" required placeholder="请输入昵称" autocomplete="nickname"></label><button class="btn full" type="submit">进入体验</button></form>`); }
async function start() { if(!S.boot.user) return login(); if(!S.boot.user.followed && (!isDemo() || inWeChat())){ try{ await api('/api/follow/refresh','POST',{}); await refreshBoot(); }catch{} } if(!(S.boot.user.rules || S.boot.user.rulesAccepted || S.boot.user.rules_accepted || S.boot.user.rulesAcceptedAt)) { nav('rules'); return; } const a=await api('/api/attempts/start','POST',{}); await openAttempt(a.id,a); }
async function openAttempt(id, initial) { S.attempt = initial || await api(`/api/attempts/${idPath(id)}`); if(S.attempt.status !== 'active' && S.attempt.status !== 'in_progress') { nav(`result/${id}`); return; } S.index=0; S.answers={...(S.attempt.answers || {})}; try { const local=JSON.parse(localStorage.getItem(`quiz-progress-${id}`) || 'null'); if(local?.answers) { S.answers={...S.answers,...local.answers}; S.dirty=true; scheduleSave(); }} catch {} nav(`quiz/${id}`); if(location.hash===`#quiz/${id}`) renderQuiz(); }
function answerCount() { return (S.attempt?.questions || []).filter(q=>S.answers[q.id]?.length).length; }
function renderQuiz() { const a=S.attempt; if(!a?.questions?.length) return shell(empty('未获取到试题，请返回首页重试。')); const q=a.questions[S.index], multi=q.type==='multiple' || q.type==='multi'; shell(`<div class="narrow"><div class="question-head"><span class="question-type ${multi?'multi':'single'}">${multi?esc(copy('quizMulti','多选题')):esc(copy('quizSingle','单选题'))}</span><span class="timer" id="countdown" aria-label="剩余答题时间">--:--</span></div><section class="card"><div class="answer-mode ${multi?'multi':'single'}"><strong>${multi?esc(copy('quizMulti','多选题')):esc(copy('quizSingle','单选题'))}</strong><span>${multi?esc(copy('quizHelpMulti','至少选 2 项，全部选对才得分；漏选、错选均不得分。')):esc(copy('quizHelpSingle','只能选 1 项，选对得 8 分。'))}</span></div><div class="question-head"><strong>第 ${String(S.index+1).padStart(2,'0')} 题 <span class="muted">/ ${a.questions.length}</span></strong><span class="muted">已完成 ${answerCount()} 题</span></div><div class="progress-track"><i style="width:${answerCount()/a.questions.length*100}%"></i></div><h1 class="question-stem">${esc(q.stem)}</h1><div class="options">${q.options.map((o,i)=>`<button class="option ${(S.answers[q.id]||[]).includes(o.id)?'selected':''}" data-action="option" data-option="${esc(o.id)}" aria-pressed="${(S.answers[q.id]||[]).includes(o.id)}"><span class="option-letter">${['①','②','③','④','⑤'][i]}</span><span>${esc(o.text)}</span></button>`).join('')}</div><p class="help">${multi?'多选题：至少选 2 项，全部选对才得分；漏选、错选均不得分。':'单选题：只能选 1 项，选对得 8 分。'}</p><div class="question-actions"><button class="btn secondary" data-action="prev" ${S.index===0?'disabled':''}>← 上一题</button>${S.index<a.questions.length-1?'<button class="btn" data-action="next">下一题 →</button>':'<button class="btn" data-action="submit">完成答题，交卷</button>'}</div><div class="question-map" aria-label="题号导航">${a.questions.map((item,i)=>`<button class="${S.answers[item.id]?.length?'done ':''}${S.index===i?'current':''}" data-action="jump" data-index="${i}" aria-label="第${i+1}题${S.answers[item.id]?.length?'，已答':'，未答'}">${i+1}</button>`).join('')}</div><div class="save-status" id="save-status">${S.dirty?'正在保存答题进度…':'进度已同步，退出后可在有效期内续答'}</div></section><div class="action-row"><button class="text-link" data-action="save-exit">保存并返回首页</button>${S.index<a.questions.length-1?'<button class="text-link" data-action="submit">提前交卷</button>':''}</div></div>`); clearInterval(S.timer); tick(); S.timer=setInterval(tick,1000); }
function scheduleSave() { S.dirty=true; try { localStorage.setItem(`quiz-progress-${S.attempt.id}`,JSON.stringify({answers:S.answers})); } catch {} clearTimeout(S.saveTimer); S.saveTimer=setTimeout(()=>saveAnswers().catch(()=>{}),650); }
let saveChain=Promise.resolve();
function saveAnswers() { if(!S.attempt || !S.dirty) return saveChain; const id=S.attempt.id, answers=JSON.parse(JSON.stringify(S.answers)); S.dirty=false; saveChain=saveChain.catch(()=>{}).then(async()=>{ try { await api(`/api/attempts/${idPath(id)}/answers`,'PUT',{answers}); if(!S.dirty && JSON.stringify(S.answers)===JSON.stringify(answers)){try{localStorage.removeItem(`quiz-progress-${id}`);}catch{}} if($('#save-status')) $('#save-status').textContent=S.dirty?'正在同步最新进度…':'进度已同步'; } catch(e) { S.dirty=true; if($('#save-status')) $('#save-status').textContent='网络异常，进度已保存在此设备；请联网后重试'; throw e; }}); return saveChain; }
function tick() { if(!S.attempt || S.submitting) return; const end=new Date(S.attempt.deadlineAt).getTime(); if(!Number.isFinite(end)) { if($('#countdown')) $('#countdown').textContent='不限时'; return; } const sec=Math.max(0,Math.ceil((end-Date.now()-(S.clockOffset || 0))/1000)); if($('#countdown')) $('#countdown').textContent=`${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`; if(sec===0) { clearInterval(S.timer); submitAttempt(true).catch(e=>toast(e.message)); }}
async function submitAttempt(auto=false) { if(S.submitting) return; const missing=S.attempt.questions.length-answerCount(); if(!auto && missing && !confirm(`还有 ${missing} 道题未作答，未答题不得分。确定交卷吗？`)) return; S.submitting=true; clearTimeout(S.saveTimer); clearInterval(S.timer); try { await saveChain.catch(()=>{}); const r=await api(`/api/attempts/${idPath(S.attempt.id)}/submit`,'POST',{answers:S.answers}); S.attempt=r; S.dirty=false; try {localStorage.removeItem(`quiz-progress-${r.id}`);} catch {} await refreshBoot(); if(auto) toast('答题时间已结束，已自动交卷'); nav(`result/${r.id}`); } catch(e) { modal('交卷未完成',`<p>${esc(e.message)}</p><p class="help">答案仍保存在此设备。请恢复网络后重试，最终状态以服务器为准。</p><button class="btn full" data-action="retry-submit">重试交卷</button>`); } finally { S.submitting=false; }}
function analysisHTML(a) { return ''; }
async function result(id) { const a=await api(`/api/attempts/${idPath(id)}`); S.attempt=a; const expired=a.status==='expired'; shell(`<div class="narrow"><a class="back" href="#home">← 返回首页</a><section class="card"><div class="result-header"><div class="eyebrow">${expired?esc(copy('resultExpiredEyebrow','本次答题已过期')):esc(copy('resultEyebrow','本次成绩'))}</div><h2>${expired?esc(copy('resultExpiredTitle','本次答题已过期')):a.passed?esc(copy('resultPassTitle','答题达标，收获满满！')):esc(copy('resultFailTitle','再接再厉，平安知识多一分'))}</h2><div class="score">${a.score ?? '—'}<small>/ 100 分</small></div><p class="help">${expired?esc(copy('resultExpiredTip','本次状态及机会归还以服务器记录为准。')):a.passed?(a.drawn?(a.lottery?.won?esc(copy('resultDrawnTip','已中奖，可在“我的奖品”查看结果。')):esc(copy('resultDrawnTip','已抽奖，感谢参与。'))):esc(copy('resultPassTip',`已达到 ${cfg().passScore || 80} 分抽奖门槛，快去揭晓你的好礼。`))):esc(copy('resultFailTip','学习的每一步都有意义，再来一次巩固知识吧。'))}</p></div><div class="action-row">${a.passed?(a.drawn?(a.lottery?.won?`<a class="btn" href="#awards">查看抽奖结果 →</a>`:''):`<a class="btn" href="#lottery/${esc(a.id)}">去转盘，抽好礼 →</a>`):!expired&&S.boot.account?.canRevive?'<button class="btn" data-action="revive">了解复活方式 →</button>':''}<a class="btn secondary" href="#ranking">${esc(copy('resultRankingButton','查看积分榜'))}</a><a class="btn secondary" href="#home">${esc(copy('resultHomeButton','返回首页'))}</a></div>${cfg().resultTip?`<p class="help center">${esc(cfg().resultTip)}</p>`:''}</section>${analysisHTML(a)}</div>`); }
function reviveModal() { const mode=cfg().shareMode; modal('再一次，向达标出发',`<p>本次答题未达标，可按已开放的方式申请当日复活机会。</p><div class="notice-box">${mode==='disabled'?'当前未开放复活申请。':mode==='manual'?'当前启用人工确认方式。请先阅读并完成活动要求，确认后由服务端核验资格。':mode==='free'?'当前无需分享即可申请，是否开放以服务端校验为准。':'微信分享能力仅用于配置分享内容，不将“调起分享”或配置回调当作已成功转发。'}</div>${cfg().shareUrl?`<a class="btn secondary full" target="_blank" rel="noopener" href="${safeURL(cfg().shareUrl)}">打开活动文章</a>`:''}${mode==='free'?'<button class="btn full" data-action="confirm-revive">申请当日复活机会</button>':mode!=='disabled'?'<p class="help">请在微信右上角菜单分享。仅在确已完成且活动允许手动确认时提交申请。</p><button class="btn full" data-action="confirm-revive">我确认已完成，申请复活</button>':''}`); if(mode==='sdk')setupShare().catch(e=>toast(e.message)); }
function safeURL(v) { try { const u=new URL(v,location.origin); return ['https:','http:'].includes(u.protocol)?esc(u.href):'#'; } catch {return '#';} }
async function setupShare() { if(!/MicroMessenger/i.test(navigator.userAgent)) return; const conf=await api(`/api/share/config?url=${encodeURIComponent(location.href.split('#')[0])}`); if(!window.wx) await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://res.wx.qq.com/open/js/jweixin-1.6.0.js';script.onload=resolve;script.onerror=()=>reject(new Error('微信分享组件暂不可用，请使用右上角菜单'));document.head.appendChild(script);}); const {imgUrl,...wxConf}=conf; window.wx.config({...wxConf,jsApiList:['updateAppMessageShareData','updateTimelineShareData','requestMerchantTransfer']}); window.wx.error(err=>console.warn('wx.config',err)); window.wx.ready(()=>{ const data={title:cfg().title,desc:'学法守法，共建平安家园',link:cfg().shareUrl || location.href.split('#')[0]}; if(imgUrl) data.imgUrl=imgUrl; window.wx.updateAppMessageShareData?.(data); window.wx.updateTimelineShareData?.(data); }); }
async function lottery(id) { try{await refreshBoot();}catch{} S.attempt=await api(`/api/attempts/${idPath(id)}`); const drawn=!!S.attempt.drawn, l=S.attempt.lottery; const wheelPrizes=(S.boot.prizes||[]).slice(0,6); const prizes=wheelPrizes.length?wheelPrizes.map(p=>[p.name,p.type==='none'?'未中奖':p.type==='points'?'直接入账':p.type==='cash'?'微信红包':'奖品']):[['谢谢惠顾','未中奖']]; const labels=prizes.map((p,i)=>`<div class="wheel-label ${i%2===0?'on-red':'on-cream'}" style="--a:${i*60+30}deg">${esc(p[0])}</div>`).join(''); const initial=drawn&&l?`<h3>${esc(l.message)}</h3>${l.prize?`<p class="prize-name">${esc(l.prize)}</p>`:''}<a class="btn" href="#awards">查看记录 →</a>`:`<p class="help">${isDemo()?'演示抽奖，不发放真实红包或实物。':'每套达标成绩仅可抽取一次，重复操作返回原抽奖结果。'}</p>`; shell(`<div class="narrow"><a class="back" href="#result/${esc(id)}">← 返回成绩</a><section class="card center lottery-card"><div class="eyebrow">${esc(copy('lotteryEyebrow','答题有礼'))}</div><h2>${esc(copy('lotteryTitle','答题有礼，好运开启'))}</h2><p class="help">本次 ${S.attempt.score ?? '—'} 分 · ${S.attempt.passed?'已获得抽奖资格':'未获得抽奖资格'}</p><div class="wheel-wrap"><div class="wheel-pointer"></div><div class="wheel" id="wheel">${labels}</div><button class="wheel-center" id="wheel-btn" type="button" data-action="draw" ${(!S.attempt.passed||drawn)?'disabled':''}>${drawn?'已抽奖':'抽奖'}</button></div><div id="draw-result" class="wheel-result">${initial}</div></section></div>`); }
function animateWheel(wheel,target,duration=3200){ return new Promise(resolve=>{ const start=performance.now(); const from=0; const frame=now=>{ if(!document.body.contains(wheel)){ resolve(); return; } const p=Math.min(1,(now-start)/duration); const eased=1-Math.pow(1-p,3); wheel.style.transform=`rotate(${from+(target-from)*eased}deg)`; if(p<1) requestAnimationFrame(frame); else resolve(); }; requestAnimationFrame(frame); }); }
async function draw() { const button=$('#wheel-btn'), wheel=$('#wheel'); if(!button || !wheel || button.disabled) return; button.disabled=true; button.textContent='抽奖中'; try { const r=await api('/api/lottery','POST',{attemptId:S.attempt.id}); const names=(S.boot.prizes||[]).map(p=>p.name); let idx=0; if(r.won && r.prize){ const found=names.indexOf(r.prize.name); if(found>=0) idx=found; } const angle=360*3+(360-(idx*60+30)); wheel.classList.add('spinning'); await animateWheel(wheel,angle,3200); wheel.classList.remove('spinning'); button.textContent='已抽奖'; const box=$('#draw-result'); if(box) box.innerHTML=`<h3>${esc(r.message || (r.won?'恭喜获得奖品':'感谢参与，继续学习！'))}</h3>${r.prize?`<p class="prize-name">${esc(r.prize.name)}</p>`:''}${r.order?`<p class="help">发放状态：${esc(orderStatusName(r.order.status))}。${isDemo()?'仅为演示记录，不代表真实到账。':'现金是否到账请以微信及发放记录为准。'}</p><a class="btn" href="#awards">查看记录 / 登记领奖信息 →</a>`:'<a class="btn secondary" href="#home">返回首页</a>'}`; try{await refreshBoot();}catch{} } catch(e) { button.disabled=false; button.textContent='抽奖'; throw e; } }
async function ranking(winners=false) { const r=await api('/api/leaderboard'+(winners?'?winners=1':'')); const testBar=S.boot.user?.is_test?`<div class="test-bar"><span>测试账号</span><button class="btn small secondary" data-action="${r.frozen?'test-unfreeze':'test-freeze'}">${r.frozen?'解除测试封榜':'测试封榜'}</button></div>`:''; const rows=winners?r.rows.filter(x=>Number(x.rank)<=Number(cfg().winnerCount || 50)):r.rows; shell(`<div class="narrow">${testBar}<div class="page-heading"><div><div class="eyebrow">${winners?esc(copy('winnersEyebrow','荣誉榜单')):esc(copy('rankingEyebrow','共同进步'))}</div><h1>${winners?esc(copy('winnersTitle','获奖名单公示')):esc(copy('rankingTitle','每一分努力，都值得被看见'))}</h1><p>${r.frozen?esc(copy('winnersIntro','榜单已封存，排名以最终公示为准')):esc(copy('rankingIntro','榜单更新中，活动结束后冻结最终排名'))}</p></div><span class="chip ${r.frozen?'gold':'green'}">${r.frozen?'已封榜':'实时榜单'}</span></div>${winners?`<div class="notice-box">评优奖励：${esc(cfg().awardDescription || '以主办方正式公告为准')}</div>`:''}${winners&&!r.frozen?'<div class="notice-box">活动尚未封榜，以下仅为当前排名预览，并非最终获奖名单。</div>':''}${r.me?`<section class="card rank-me"><div class="question-head" style="margin:0"><strong>我的排名 · ${r.me.rank ?? '暂未上榜'}</strong><span>${r.me.points ?? 0} 积分</span></div></section><br>`:''}<section class="card"><div class="section-heading" style="margin-top:0"><h2>${winners?`前 ${cfg().winnerCount || 50} 名荣誉榜`:`积分榜前 ${cfg().leaderboardLimit || 100}`}</h2><a class="text-link" href="#${winners?'awards':'winners'}">${winners?'我的领奖信息':'获奖公示'} →</a></div>${rows.length?`<div class="table-scroll"><table class="rank-table"><thead><tr><th>排名</th><th>参与者</th><th>累计积分</th><th>总用时</th></tr></thead><tbody>${rows.map(x=>`<tr><td><span class="rank-number">${esc(x.rank)}</span></td><td>${esc(x.nickname || '微信用户')}</td><td><strong>${esc(x.points)}</strong></td><td>${Math.round(x.totalSeconds || 0)} 秒</td></tr>`).join('')}</tbody></table></div>`:empty(copy('rankingEmpty','还没有上榜记录，快来开启你的知识之旅。'))}</section><p class="help center">${esc(copy('rankingHelp','按所有已提交成绩的最高分（低于 80 分也可上榜）加抽奖积分排名，多套不累计。'))}同分依次比较用时，昵称已脱敏展示。</p></div>`,'ranking'); }
async function awards() { if(!S.boot.user) { shell(`<div class="narrow card center"><h2>我的奖品</h2><p class="muted">登录后查看中奖记录与领奖信息。</p><button class="btn" data-action="login">登录参与</button></div>`,'awards'); return; } const {orders}=await api('/api/orders'); S.data=orders; shell(`<div class="narrow"><div class="page-heading"><div><div class="eyebrow">${esc(copy('awardsEyebrow','我的奖品'))}</div><h1>${esc(copy('awardsTitle','我的奖品'))}</h1><p>${esc(copy('awardsIntro','记录每一份收获，也感谢你的每一次参与。'))}</p></div><a class="text-link" href="#winners">获奖公示 →</a></div><section class="card">${orders.length?orders.map(o=>`<article class="order-card"><div class="order-top"><h3>${esc(o.prize_name || o.prizeName || o.prize?.name || o.name || '活动奖品')}</h3><span class="chip ${o.status==='paid'?'green':'gold'}">${esc(orderStatusName(o.status))}</span></div><p>订单号：${esc(o.id)}<br>获得时间：${date(o.createdAt || (o.created ? o.created * 1000 : null))}${o.tracking?`<br>物流单号：${esc(o.tracking)}`:''}${(o.failureReason || o.failure)?`<br>发放说明：${esc(o.failureReason || o.failure)}`:''}</p>${isDemo()?'<p class="help">演示记录 · 不代表真实发放或资金到账</p>':''}${(o.type || o.prizeType || o.prize?.type)==='cash'?`<p class="help">待确认收款表示需要你在微信中确认；确认后状态更新，只有已到账才表示领取成功。</p>${o.status==='wait_confirm'&&o.packageInfo?`<button class="btn small" data-action="confirm-transfer" data-id="${esc(o.id)}">确认收款</button>`:''}<button class="btn small secondary" data-action="refresh-awards">刷新发放状态</button>`:(o.type || o.prizeType || o.prize?.type)==='points'?'<p class="help">积分奖励已直接计入总积分，无需登记收货信息。</p>':(o.type || o.prizeType || o.prize?.type)==='phone'?`<button class="btn small secondary" data-action="claim" data-id="${esc(o.id)}">${o.recipient?.phone?'查看 / 修改手机号':'填写手机号'}</button>`:`<button class="btn small secondary" data-action="claim" data-id="${esc(o.id)}">${o.recipient?.name || o.address || o.claim?.address || o.claimName?'查看 / 更新领奖信息':'填写领奖信息'}</button>`}</article>`).join(''):empty(copy('awardsEmpty','暂无中奖记录。完成答题并达标后，可参与好礼抽取。'))}</section><p class="help">您的个人信息仅用于本次活动奖品寄送或线下核验，不会用于其他用途，也不会向无关第三方泄露。</p></div>`,'awards'); }
function claimModal(id) { const o=(S.data||[]).find(x=>String(x.id)===String(id)) || {}, d=o.recipient || o.claim || o; if((o.type||o.prizeType||o.prize?.type)==='phone'){ modal('填写话费领取手机号',`<form id="claim-form" data-id="${esc(id)}"><label class="field">手机号<input name="phone" required inputmode="tel" pattern="1[3-9][0-9]{9}" maxlength="11" value="${esc(d.phone || '')}" autocomplete="tel"></label><div class="privacy-note">您的手机号仅用于本次活动话费奖励发放，不会用于其他用途，也不会向无关第三方泄露。</div><p class="help">活动结束后由主办方统一发放话费，请确认号码准确。</p><button class="btn full" type="submit">保存手机号</button></form>`); return; } modal('登记领奖信息',`<form id="claim-form" data-id="${esc(id)}"><label class="field">收件人姓名<input name="name" required maxlength="40" value="${esc(d.claimName || d.recipientName || d.name || '')}" autocomplete="name"></label><label class="field">联系电话<input name="phone" required inputmode="tel" pattern="1[3-9][0-9]{9}" maxlength="11" value="${esc(d.phone || '')}" autocomplete="tel"></label><label class="field check"><input type="checkbox" name="pickup" ${d.pickup?'checked':''}>选择线下领取（地点以主办方通知为准）</label><label class="field">收货地址 / 线下领取备注<textarea name="address" maxlength="300" autocomplete="street-address">${esc(d.address || '')}</textarea></label><div class="privacy-note">您的姓名、电话和地址仅用于本次活动奖品发放，不会用于其他用途，也不会向无关第三方泄露。提交前请核对信息。</div><p class="help">请填写真实信息，以便主办方寄送奖品或通知线下领取。</p><button class="btn full" type="submit">保存领奖信息</button></form>`); }
const adminTabs=[['dashboard','dashboard','运营概览'],['config','settings','活动配置'],['theme','palette','个性主题'],['questions','rules','题库管理'],['prizes','gift','奖品管理'],['users','users','用户管理'],['integrations','link','微信配置'],['records','records','记录与发奖']];
function adminShell(content) { app.innerHTML=`<div class="admin-shell"><aside class="admin-sidebar">${brand()}<nav class="admin-nav">${adminTabs.map(([r,i,t])=>`<a href="#admin/${r}" class="${S.adminTab===r?'active':''}">${icon(i)}<span>${t}</span></a>`).join('')}</nav><div class="admin-sidebar-foot">活动运营工作台<br><a href="#home">← 返回活动页面</a></div></aside><div class="admin-main"><header class="admin-topbar"><strong>扫黑除恶 · 有奖答题管理平台</strong><button class="text-link" data-action="admin-logout">退出管理</button></header>${demoRibbon()}<main class="admin-content">${content}</main></div></div>`; }
function adminHeading(title,description) { return `<div class="admin-heading"><div class="eyebrow">运营管理</div><h1>${title}</h1><p>${description}</p></div>`; }
function adminLogin() { app.innerHTML=`<div class="page"><section class="card login-card">${brand()}<h2 class="center">活动管理后台</h2><p class="help center" style="margin-bottom:24px">请使用管理员账号安全登录</p><form id="admin-login"><label class="field">账号<input name="username" required autocomplete="username" placeholder="管理员账号"></label><label class="field">密码<input name="password" required type="password" autocomplete="current-password" placeholder="请输入密码"></label><button class="btn full" type="submit">登录工作台 →</button></form><p class="help center"><a href="#home">返回活动首页</a></p></section></div>`; }
async function adminPage(tab) { S.adminTab=tab || 'dashboard'; try { if(S.adminTab==='dashboard') {const d=await api('/api/admin/dashboard'); S.admin=true; adminShell(adminHeading('运营概览','掌握参与情况，稳妥推进活动与奖品发放。')+`<div class="metric-grid">${[['参与人数',d.stats.users],['答题套次',d.stats.attempts],['达标套次',d.stats.passed],['中奖订单',d.stats.orders],['已用预算 / 元',money(d.stats.spentCents)]].map(([t,v])=>`<section class="card metric"><span>${t}</span><strong>${esc(v ?? 0)}</strong></section>`).join('')}</div><div class="admin-columns single"><section class="card"><div class="card-title">运行提醒</div>${(d.warnings||[]).length?d.warnings.map(x=>`<div class="notice-box">${esc(typeof x==='string'?x:x.message || x.detail)}</div>`).join(''):empty('暂无运行异常提醒')}</section><section class="card"><div class="card-title">活动控制</div><div class="inline-buttons"><button class="btn small secondary" data-action="unfreeze-activity" ${d.frozen?'':'disabled'}>解除封榜</button><button class="btn small ghost" data-action="reset-activity">重置活动数据</button></div><p class="help">解除封榜会清除封榜快照和话费订单，保留用户与答题记录；重置活动会清空所有用户、答题、抽奖和订单，保留题库、奖品、活动配置和微信配置。</p></section></div>`); }
else if(S.adminTab==='config') await configPage(); else if(S.adminTab==='theme') await themePage(); else if(S.adminTab==='questions') await questionsPage(); else if(S.adminTab==='prizes') await prizesPage(); else if(S.adminTab==='integrations') await integrationsPage(); else if(S.adminTab==='users') await usersPage(); else if(S.adminTab==='records') await recordsPage(); else nav('admin/dashboard'); } catch(e) { if(e.status===401 || e.status===403) {S.admin=false;adminLogin();} else throw e; } }
function field(label,name,value,type='text',hint='') { return `<label class="field">${esc(label)}<input name="${name}" type="${type}" value="${esc(value ?? '')}" ${type==='number'?'min="0" step="1"':''}>${hint?`<small>${esc(hint)}</small>`:''}</label>`; }
function checkField(label,name,value) {return `<label class="field check"><input type="checkbox" name="${name}" ${value?'checked':''}>${esc(label)}</label>`;}
function localDatetime(v) { if(!v)return '';const d=new Date(v); if(!Number.isFinite(d.getTime()))return '';const z=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${z(d.getMonth()+1)}-${z(d.getDate())}T${z(d.getHours())}:${z(d.getMinutes())}`; }
