async function prizesPage() { const d=await api('/api/admin/prizes'); S.data=d.prizes; adminShell(adminHeading('奖品管理','设置档位、库存、投放上限与权重，未中奖档位同样参与权重计算。')+`<section class="card"><div class="toolbar"><button class="btn small" data-action="new-prize">＋ 新增奖品</button><button class="btn small secondary" data-action="refresh-prizes">刷新库存</button></div><div class="table-scroll"><table class="admin-table"><thead><tr><th>奖品名称</th><th>类型</th><th>金额 / 元</th><th>总量</th><th>已发</th><th>剩余</th><th>每日上限</th><th>权重</th><th>状态</th><th>操作</th></tr></thead><tbody>${d.prizes.map(p=>`<tr><td>${esc(p.name)}</td><td>${({cash:'红包',physical:'实物',souvenir:'宣传品',none:'未中奖',points:'积分'})[p.type] || esc(p.type)}</td><td>${p.type==='points'?`+${p.points || 0} 积分`:money(p.amountCents)}</td><td>${p.stock ?? 0}</td><td>${p.issued ?? 0}</td><td>${p.remaining ?? 0}</td><td>${p.dailyLimit ?? 0}</td><td>${p.weight ?? 0}</td><td><span class="chip ${Number(p.enabled)?'green':''}">${Number(p.enabled)?'上架':'下架'}</span></td><td><button class="btn small secondary" data-action="edit-prize" data-id="${esc(p.id)}">编辑</button></td></tr>`).join('')}</tbody></table></div>${!d.prizes.length?empty('暂无奖品，请按已批复的预算配置。'):''}</section>`); }
